@inline
def gc_rates(
    ex: float, ey: float, ez: float,
    bx: float, by: float, bz: float,
    gx: float, gy: float, gz: float,
    kx: float, ky: float, kz: float,
    v_par: float, mu: float, charge: float, mass: float,
) -> tuple[float, float, float, float]:
    """Return ``dX/dt`` (three components) and ``dv_par/dt`` of a guiding centre.

    ``e``, ``b``, ``g`` (grad B) and ``k`` (the curvature ``(b . grad) b``) are the
    fields at the marker; ``mu`` the magnetic moment.
    """
    return (
        v_par * (bx / sqrt(bx * bx + by * by + bz * bz))
        + (ey * bz - ez * by) * (1.0 / (bx * bx + by * by + bz * bz))
        + (mu / (charge * sqrt(bx * bx + by * by + bz * bz))) * ((by / sqrt(bx * bx + by * by + bz * bz)) * gz - (bz / sqrt(bx * bx + by * by + bz * bz)) * gy)
        + (mass * v_par * v_par / (charge * sqrt(bx * bx + by * by + bz * bz))) * ((by / sqrt(bx * bx + by * by + bz * bz)) * kz - (bz / sqrt(bx * bx + by * by + bz * bz)) * ky),
        v_par * (by / sqrt(bx * bx + by * by + bz * bz))
        + (ez * bx - ex * bz) * (1.0 / (bx * bx + by * by + bz * bz))
        + (mu / (charge * sqrt(bx * bx + by * by + bz * bz))) * ((bz / sqrt(bx * bx + by * by + bz * bz)) * gx - (bx / sqrt(bx * bx + by * by + bz * bz)) * gz)
        + (mass * v_par * v_par / (charge * sqrt(bx * bx + by * by + bz * bz))) * ((bz / sqrt(bx * bx + by * by + bz * bz)) * kx - (bx / sqrt(bx * bx + by * by + bz * bz)) * kz),
        v_par * (bz / sqrt(bx * bx + by * by + bz * bz))
        + (ex * by - ey * bx) * (1.0 / (bx * bx + by * by + bz * bz))
        + (mu / (charge * sqrt(bx * bx + by * by + bz * bz))) * ((bx / sqrt(bx * bx + by * by + bz * bz)) * gy - (by / sqrt(bx * bx + by * by + bz * bz)) * gx)
        + (mass * v_par * v_par / (charge * sqrt(bx * bx + by * by + bz * bz))) * ((bx / sqrt(bx * bx + by * by + bz * bz)) * ky - (by / sqrt(bx * bx + by * by + bz * bz)) * kx),
        (charge / mass) * (ex * (bx / sqrt(bx * bx + by * by + bz * bz)) + ey * (by / sqrt(bx * bx + by * by + bz * bz)) + ez * (bz / sqrt(bx * bx + by * by + bz * bz)))
        - (mu / mass) * ((bx / sqrt(bx * bx + by * by + bz * bz)) * gx + (by / sqrt(bx * bx + by * by + bz * bz)) * gy + (bz / sqrt(bx * bx + by * by + bz * bz)) * gz),
    )


